bool validate_tx(Transaction tx, UTXOSet *set) {
    Amount in_total = 0;
    Amount out_total = 0;
    for (size_t i = 0; i < tx.input_count; i++) {
        UTXO *u = utxo_lookup(set, tx.inputs[i].prevout);
        if (u == NULL || u->already_spent) return false;
        if (!verify_spend_condition(tx, i, u->locking_script)) return false;
        in_total += u->value;
    }
    for (size_t j = 0; j < tx.output_count; j++) {
        if (tx.outputs[j].value < 0) return false;
        out_total += tx.outputs[j].value;
    }
    if (out_total > in_total) return false;
    return true; // simplified: real validation includes many more consensus checks
}

